package local

import (
	"embed"
	"io/fs"
)

// The bundle is generated by the release of the Sentinel runtime and copied
// here; it is not edited by hand. VERSION names the commit its images are from.
//
//go:embed all:bundle
var embedded embed.FS

// Bundle is the bundle this build of the command brings up.
func Bundle() fs.FS {
	sub, err := fs.Sub(embedded, "bundle")
	if err != nil {
		panic(err)
	}
	return sub
}
